// Live TV JavaScript - Main functionality

class LiveTV {
    constructor() {
        this.currentChannelId = 1;
        this.currentScrollPosition = 0;
        this.timeSlotWidth = 300; // 30 minutes = 300px => 1 minute = 10px
        this.scheduleData = [];
        this.isPlaying = false;
        this.volume = 1;
        this.currentVideoIndex = 0;
        this.videoPlaylist = [];
        this.selectedChannelData = null;
        this.hls = null;
        this.equalizerAnimationId = null;
        this.isManualPause = false; // Track if user manually paused
        this.channelPlaybackCache = new Map();
        this.channelPlaybackCacheTtlMs = 10 * 60 * 1000;
        this.streamUrlRefreshSkewMs = 60 * 1000;
        this.isRefreshingStreamUrl = false;
        this.lastStreamRefreshAt = 0;
        this.streamRefreshCooldownMs = 5000;
        this.playbackRequestId = 0; // Used to invalidate stale async playback calls
        this.isReloadingSchedules = false;
        this.doubleTapGuardInitialized = false;
        this.isScheduleDragActive = false;
        this.lastScheduleDragTs = 0;
        this.orientationAutoFullscreenActive = false;
        this.audioContextUnlockBound = false;
        this.audioContextUnlockHandler = null;

        this.init();
    }

    // Generates the HTML for the equalizer bars
    generateEqualizerBars() {
        const barCount = 52; // 60 - 8 (4 from each side)
        let bars = '';
        for (let i = 0; i < barCount; i++) {
            bars += `<div class="equalizer-bar"></div>`;
        }
        return bars;
    }

    setupAudioContextAutoResume() {
        if (this.audioContextUnlockBound) return;

        this.audioContextUnlockHandler = () => {
            this.ensureAudioContextReady().then((isReady) => {
                if (isReady) {
                    this.removeAudioContextAutoResume();
                }
            });
        };

        ['touchstart', 'pointerdown', 'click', 'keydown'].forEach((eventName) => {
            document.addEventListener(eventName, this.audioContextUnlockHandler, true);
        });

        this.audioContextUnlockBound = true;
    }

    removeAudioContextAutoResume() {
        if (!this.audioContextUnlockBound || !this.audioContextUnlockHandler) return;

        ['touchstart', 'pointerdown', 'click', 'keydown'].forEach((eventName) => {
            document.removeEventListener(eventName, this.audioContextUnlockHandler, true);
        });

        this.audioContextUnlockBound = false;
        this.audioContextUnlockHandler = null;
    }

    async ensureAudioContextReady() {
        try {
            if (!this.audioContext) {
                const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
                if (!AudioContextCtor) {
                    return false;
                }
                this.audioContext = new AudioContextCtor();
            }

            if (this.audioContext.state === 'suspended') {
                await this.audioContext.resume();
            }

            return this.audioContext.state === 'running';
        } catch (e) {
            return false;
        }
    }

    // Initializes the real equalizer animation
    startEqualizerAnimation() {
        const audio = document.getElementById('live-audio');
        if (!audio) return;

        if (!audio.crossOrigin) {
            audio.crossOrigin = 'anonymous';
            audio.setAttribute('crossorigin', 'anonymous');
        }

        this.ensureAudioContextReady().then((contextReady) => {
            if (!contextReady) {
                this.startFallbackAnimation();
                return;
            }

            try {
                // Disconnects the previous audio source
                if (this.audioSource && this.connectedAudioElement !== audio) {
                    try {
                        this.audioSource.disconnect();
                    } catch (e) {}
                    this.audioSource = null;
                }

                // Creates a new analyzer if needed
                if (!this.analyser || this.connectedAudioElement !== audio) {
                    this.analyser = this.audioContext.createAnalyser();
                    this.analyser.fftSize = 128;
                    this.analyser.smoothingTimeConstant = 0.8;
                }

                // Connects the audio element to the analyzer
                if (!this.audioSource || this.connectedAudioElement !== audio) {
                    this.audioSource = this.audioContext.createMediaElementSource(audio);
                    this.audioSource.connect(this.analyser);
                    this.analyser.connect(this.audioContext.destination);
                    this.connectedAudioElement = audio;
                }

                if (this.equalizerAnimationId) {
                    cancelAnimationFrame(this.equalizerAnimationId);
                    this.equalizerAnimationId = null;
                }

                document.querySelectorAll('.equalizer-bar').forEach(bar => bar.classList.remove('active'));
                this.dataArray = new Uint8Array(this.analyser.frequencyBinCount);
                this.isEqualizerRunning = true;
                this.animateEqualizer();
            } catch (e) {
                console.log('Web Audio API error, using fallback animation:', e);
                this.startFallbackAnimation();
            }
        });
    }

    // Handles the equalizer animation logic
    animateEqualizer() {
        if (!this.isEqualizerRunning) return;

        const bars = document.querySelectorAll('.equalizer-bar');
        if (bars.length === 0 || !this.analyser) {
            this.equalizerAnimationId = requestAnimationFrame(() => this.animateEqualizer());
            return;
        }

        this.analyser.getByteFrequencyData(this.dataArray);

        const barCount = bars.length;
        const halfBars = Math.floor(barCount / 2);

        // Calculates responsive height for bars
        const maxHeight = Math.min(60, window.innerWidth * 0.04);
        const minHeight = Math.max(4, window.innerWidth * 0.003);

        // Maps frequency data to bar heights
