    applyMediaSessionNoSeekLock() {
        if (!('mediaSession' in navigator)) return;

        // Remove seek/skip actions so PiP controller does not show +/-10s buttons.
        ['seekbackward', 'seekforward', 'seekto', 'previoustrack', 'nexttrack', 'skipad'].forEach((action) => {
            try {
                navigator.mediaSession.setActionHandler(action, null);
            } catch (e) {
                // Some browsers do not support all media session actions.
            }
        });

        // Clear position state for live playback so seek UI is less likely to appear in PiP.
        if (typeof navigator.mediaSession.setPositionState === 'function') {
            try {
                navigator.mediaSession.setPositionState();
            } catch (e) {
                // Ignore unsupported position-state updates.
            }
        }
    }

    attachLiveSeekGuard(mediaElement, livePointProvider = null) {
        if (!mediaElement || mediaElement.tagName !== 'VIDEO') return;

        let seekGuardArmed = false;
        let suppressCorrection = false;
        let lastSafeTime = Number(mediaElement.currentTime) || 0;

        mediaElement.classList.add('no-seek');
        mediaElement.controls = false;
        mediaElement.setAttribute('controlsList', 'nodownload noplaybackrate noremoteplayback');
        mediaElement.setAttribute('disablePictureInPicture', '');
        mediaElement.setAttribute('disableremoteplayback', '');

        const armSeekGuard = () => {
            setTimeout(() => {
                seekGuardArmed = true;
            }, 450);
        };

        const updateSafeTime = () => {
            const current = Number(mediaElement.currentTime);
            if (Number.isFinite(current) && current >= 0) {
                lastSafeTime = current;
            }
        };

        mediaElement.addEventListener('loadedmetadata', () => {
            updateSafeTime();
            armSeekGuard();
        });

        mediaElement.addEventListener('timeupdate', () => {
            if (!mediaElement.seeking && !suppressCorrection) {
                updateSafeTime();
            }
        });

        mediaElement.addEventListener('seeking', () => {
            if (!seekGuardArmed || suppressCorrection) {
                return;
            }

            let targetTime = lastSafeTime;
            if (typeof livePointProvider === 'function') {
                const livePoint = Number(livePointProvider());
                if (Number.isFinite(livePoint)) {
                    targetTime = livePoint;
                }
            }

            if (Number.isFinite(mediaElement.duration) && mediaElement.duration > 0) {
                targetTime = Math.min(targetTime, mediaElement.duration);
            }
            targetTime = Math.max(0, targetTime);

            if (Math.abs((Number(mediaElement.currentTime) || 0) - targetTime) < 0.25) {
                return;
            }

            suppressCorrection = true;
            try {
                mediaElement.currentTime = targetTime;
            } catch (e) {
                // Ignore unsupported seek corrections.
            }
            setTimeout(() => {
                suppressCorrection = false;
            }, 40);
        });
    }

    canUsePictureInPicture(videoElement) {
        if (!videoElement || videoElement.tagName !== 'VIDEO') return false;

        if (document.pictureInPictureEnabled && typeof videoElement.requestPictureInPicture === 'function') {
            return true;
        }

        if (typeof videoElement.webkitSupportsPresentationMode === 'function') {
            try {
                if (videoElement.webkitSupportsPresentationMode('picture-in-picture')) {
                    return typeof videoElement.webkitSetPresentationMode === 'function';
                }
            } catch (e) {
                return false;
            }
        }

        return typeof videoElement.webkitSetPresentationMode === 'function';
    }

    isPictureInPictureActive(videoElement = null) {
        const video = videoElement || this.getCurrentVideoElement();
        if (!video) return false;

        if (document.pictureInPictureElement === video) {
            return true;
        }

        return video.webkitPresentationMode === 'picture-in-picture';
    }

    bindPictureInPictureMediaEvents(videoElement) {
        if (!videoElement || videoElement.tagName !== 'VIDEO') return;

        const refreshState = () => {
            this.applyMediaSessionNoSeekLock();
            this.updatePictureInPictureButtonState();
        };
        videoElement.addEventListener('enterpictureinpicture', refreshState);
        videoElement.addEventListener('leavepictureinpicture', refreshState);
        videoElement.addEventListener('webkitpresentationmodechanged', refreshState);
    }

    updatePictureInPictureButtonState() {
        const pipBtn = document.querySelector('.pip-btn');
        if (!pipBtn) return;

        const video = this.getCurrentVideoElement();
        const isSupported = this.canUsePictureInPicture(video);

        pipBtn.style.display = isSupported ? 'flex' : 'none';
        pipBtn.disabled = !isSupported;

        const isActive = isSupported && this.isPictureInPictureActive(video);
        pipBtn.classList.toggle('active', isActive);
    }

    async exitPictureInPictureIfActive(videoElement = null) {
        const video = videoElement || this.getCurrentVideoElement();
        if (!video) return;

        try {
            if (document.pictureInPictureElement && document.exitPictureInPicture) {
                await document.exitPictureInPicture();
                return;
            }

            if (video.webkitPresentationMode === 'picture-in-picture' &&
                typeof video.webkitSetPresentationMode === 'function') {
                video.webkitSetPresentationMode('inline');
            }
        } catch (e) {
            // Ignore PiP exit failures.
        }
    }

    async togglePictureInPicture() {
        const video = this.getCurrentVideoElement();
        if (!this.canUsePictureInPicture(video)) {
            this.updatePictureInPictureButtonState();
            return;
        }

        this.applyMediaSessionNoSeekLock();

        try {
            if (this.isPictureInPictureActive(video)) {
                await this.exitPictureInPictureIfActive(video);
            } else if (document.pictureInPictureEnabled &&
                typeof video.requestPictureInPicture === 'function') {
                await video.requestPictureInPicture();
            } else if (typeof video.webkitSetPresentationMode === 'function') {
                video.webkitSetPresentationMode('picture-in-picture');
            }
        } catch (e) {
            console.log('PiP toggle failed:', e);
        }

        this.updatePictureInPictureButtonState();
    }

