    getSignedUrlExpiryMs(url) {
        if (!url || typeof url !== 'string') return null;

        let decodedUrl = url;
        try {
            decodedUrl = decodeURIComponent(url);
        } catch (e) {}

        let earliestExpiry = null;
        const expiryPattern = /(?:^|[?&=~;])(?:exp|expires)=?(\d{10,13})/gi;
        let match;

        while ((match = expiryPattern.exec(decodedUrl)) !== null) {
            const rawExpiry = Number(match[1]);
            if (!Number.isFinite(rawExpiry)) continue;

            const expiryMs = rawExpiry < 100000000000 ? rawExpiry * 1000 : rawExpiry;
            if (earliestExpiry === null || expiryMs < earliestExpiry) {
                earliestExpiry = expiryMs;
            }
        }

        return earliestExpiry;
    }

    getEarliestSignedUrlExpiryMs(...urls) {
        let earliestExpiry = null;

        urls.forEach((url) => {
            const expiryMs = this.getSignedUrlExpiryMs(url);
            if (!expiryMs) return;

            if (earliestExpiry === null || expiryMs < earliestExpiry) {
                earliestExpiry = expiryMs;
            }
        });

        return earliestExpiry;
    }

